import{_ as a,a as s,a3 as n,o as i}from"./chunks/framework.yJBLK5ap.js";const g=JSON.parse('{"title":"Tagging new versions","description":"","frontmatter":{},"headers":[],"relativePath":"tools/tagging/README.md","filePath":"tools/tagging/README.md","lastUpdated":1795131258000}'),t={name:"tools/tagging/README.md"};function o(r,e,l,p,c,h){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="tagging-new-versions" tabindex="-1">Tagging new versions <a class="header-anchor" href="#tagging-new-versions" aria-label="Permalink to &quot;Tagging new versions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>The file tools/git/aliases.sh contains various git aliases which are useful when using git, and may be used by the merge scripts.</p><p>The file env.sh.example contains some example environment variable settings. Copy that locally to env.sh and modify it to match your local setup.</p><p>Before running any of the other scripts, process the contents of that file as a source file</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>. env.sh</span></span></code></pre></div><p>to initialize the common environment variables.</p><h2 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h2><p>The following tools are required:</p><ul><li><strong>git</strong></li><li><strong>helm</strong></li></ul><p>The following repositories should be checked out in a directory reserved for merging and tagging (default for scripts is ~/git):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone git@github.com:hpcc-systems/eclide.git</span></span>
<span class="line"><span>git clone git@github.com:hpcc-systems/hpcc4j.git HPCC-JAPIs</span></span>
<span class="line"><span>git clone git@github.com:hpcc-systems/LN.git ln</span></span>
<span class="line"><span>git clone git@github.com:hpcc-systems/HPCC-Platform.git hpcc</span></span>
<span class="line"><span>git clone git@github.com:hpcc-systems/helm-chart.git</span></span></code></pre></div><p>The following are required for builds prior to 8.12.x</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone git@github.com:hpcc-systems/nagios-monitoring.git</span></span>
<span class="line"><span>git clone git@github.com:hpcc-systems/ganglia-monitoring.git</span></span></code></pre></div><p>The files git-fixversion and git-unupmerge can copied so they are on your default path, and then they will be available as git commands.</p><h2 id="tagging-new-versions-1" tabindex="-1">Tagging new versions <a class="header-anchor" href="#tagging-new-versions-1" aria-label="Permalink to &quot;Tagging new versions&quot;">​</a></h2><h3 id="automated-branch-maintenance" tabindex="-1">Automated branch maintenance <a class="header-anchor" href="#automated-branch-maintenance" aria-label="Permalink to &quot;Automated branch maintenance&quot;">​</a></h3><p>The root <a href="../../branch-policy.json">branch-policy.json</a> defines the ordered upmerge chain and repository enablement. The automation runs only from the default branch of <code>risk-hsy/HPCC-Platform</code>.</p><p>Three Actions entry points are available:</p><ul><li><a href="../../.github/workflows/branch-upmerge.yml">Branch Upmerge</a>: independently dispatch an internal upmerge, with <code>dry-run</code> (default) or <code>apply</code> and a repository selection.</li><li><a href="../../.github/workflows/branch-sync.yml">Branch Synchronization</a>: independently dispatch the existing OSS synchronization with the same mode/repository inputs.</li><li><a href="../../.github/workflows/branch-maintenance.yml">Daily Branch Maintenance</a>: runs upmerge then sync at <strong>23:30 UTC</strong>, and can also be dispatched manually with separate upmerge/sync modes.</li></ul><p>All three entry points share a concurrency group; reusable operation jobs do not acquire a nested lock. A cleanly aborted upmerge conflict blocks that repository&#39;s later upmerge edges, not independent repositories or the subsequent sync. Failed operations remain visible in the final run status and Actions output/summary. Issue/email/chat notifications are deferred.</p><p>The policy&#39;s <code>paused</code> flag prevents apply operations; dry-run remains available. <code>upmerge_enabled: false</code> skips sync-only repositories. A repository with one applicable branch has no upmerge edges. Multiple applicable branches must contain the complete configured chain; missing refs fail that repository without writing.</p><p>The internal App needs Contents: write and Workflows: write for upmerge apply. Dry-run requests read-only Contents access. Existing app bypass exceptions allow ordinary pushes; force pushes remain forbidden. New commits are signed off, but not cryptographically signed. No pre-push build/test/PR gate is introduced. The normalizer retains target version.cmake/POM content and patches only the HPCC chart&#39;s <code>Chart.yaml</code> version/appVersion and the <code>helmVersion</code> emitted by <code>hpcc.generateHelmVersion</code>. Component and Kubernetes API version fields are left to Git&#39;s ordinary three-way merge, preserving source-only component upgrades. Release-version conflicts in those two metadata files are normalized before merging, without executing the legacy helper&#39;s <code>eval</code> parser.</p><p>Local CLI equivalents:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tagging/upmerge-policy-branches.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> platform</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tagging/sync-oss-branches.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> platform</span></span></code></pre></div><p>For authorized local repair/apply, pause scheduled writers and wait for any active run to finish. <code>BRANCH_APP_TOKEN_INTERNAL</code> supplies internal authentication; sync additionally needs <code>BRANCH_APP_TOKEN_OSS</code>. Do not put tokens in command arguments or repository URLs. Actions inherits the existing <code>BRANCH_APP_ID_INTERNAL</code>, <code>BRANCH_APP_PRIVATE_KEY_INTERNAL</code>, <code>BRANCH_APP_ID_OSS</code>, and <code>BRANCH_APP_PRIVATE_KEY_OSS</code> secrets. Fresh sync tokens are minted after upmerge so a long upmerge does not consume their lifetime.</p><p>Run local fixture tests without accessing GitHub:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tagging/tests/test-upmerge-policy-branches.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tagging/tests/test-sync-oss-branches.sh</span></span></code></pre></div><h3 id="manual-tagging-process" tabindex="-1">Manual tagging process <a class="header-anchor" href="#manual-tagging-process" aria-label="Permalink to &quot;Manual tagging process&quot;">​</a></h3><p>The following process should be followed when tagging a new set of versions.</p><ol><li>Upmerge all changes between candidate branches for the different versions</li></ol><p>You can set the <code>all</code> environment variable to a subset of the projects (e.g. <code>export all=hpcc</code>) if there are no changes in the other repositories. The only effect for projects that are upmerged with no changes will be that they gain an empty merge transaction. If multiple people are merging PRs to different repositories it may be safer to upmerge all projects.</p><p>For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./upmerge A.a.x candidate-A.b.x</span></span>
<span class="line"><span>./upmerge A.b.x candidate-A.c.x</span></span>
<span class="line"><span>./upmerge A.b.x candidate-B.0.x</span></span>
<span class="line"><span>./upmerge B.0.x master</span></span></code></pre></div><ol start="2"><li>Create new point-release candidate branches:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./gorc.sh A.a.x</span></span>
<span class="line"><span>./gorc.sh A.b.x</span></span>
<span class="line"><span>./gorc.sh A.c.x</span></span></code></pre></div><h2 id="taking-a-build-gold" tabindex="-1">Taking a build gold: <a class="header-anchor" href="#taking-a-build-gold" aria-label="Permalink to &quot;Taking a build gold:&quot;">​</a></h2><p>Go gold with each of the explicit versions</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./gogold.sh 7.8.76</span></span>
<span class="line"><span>./gogold.sh 7.10.50</span></span></code></pre></div><p>If you have merged changes onto a point-release branch you would normally create a new rc before going gold. If the change was trivial (e.g. removing an unwanted file) then you can use the --ignore option to skip that step.</p><h2 id="creating-a-new-rc-for-an-existing-point-release" tabindex="-1">Creating a new rc for an existing point release: <a class="header-anchor" href="#creating-a-new-rc-for-an-existing-point-release" aria-label="Permalink to &quot;Creating a new rc for an existing point release:&quot;">​</a></h2><p>This normally happens after cherry-picking a late fix for a particular version, which has already been merged into the .x candidate branch.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./gorc.sh A.a.&lt;n&gt;</span></span></code></pre></div><h2 id="create-a-new-minor-major-branch" tabindex="-1">Create a new minor/major branch <a class="header-anchor" href="#create-a-new-minor-major-branch" aria-label="Permalink to &quot;Create a new minor/major branch&quot;">​</a></h2><p>A new minor branch is created from the current master...</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./gominor.sh</span></span></code></pre></div>`,46)])])}const u=a(t,[["render",o]]);export{g as __pageData,u as default};
